class Solution {
  private static int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  private static int key(int a, int b) {
    int g = gcd(a, b);
    return (a / g) << 10 | (b / g);
  }

  public long numberOfSubsequences(int[] nums) {
    int n = nums.length;
    int[] cnt = new int[1 << 20];
    long ans = 0;
    for (int r = 4; r < n - 2; r++) {
      int q = r - 2;
      for (int p = 0; p <= q - 2; p++) cnt[key(nums[p], nums[q])]++;
      for (int s = r + 2; s < n; s++) ans += cnt[key(nums[s], nums[r])];
    }
    return ans;
  }
}
